const OWNER="qoo0985797341@gmail.com",URL="https://ghroutexxxybybxtllpu.supabase.co",KEY="sb_publishable_kKI5_UiC7G0PpZABaxaBew_LIR_xmGo",client=supabase.createClient(URL,KEY);
const media=path=>!path?"":/^(https?:|assets\/)/.test(path)?path:`${URL}/storage/v1/object/public/ownver-media/${path}`;
const login=document.querySelector("#login"),studio=document.querySelector("#studio"),message=document.querySelector("#message"),library=document.querySelector("#library"),customerStories=document.querySelector("#customerStories"),form=document.querySelector("#uploadForm"),mediaRemovals=document.querySelector("#mediaRemovals"),removeVideoRow=document.querySelector("#removeVideoRow"),removeCoverRow=document.querySelector("#removeCoverRow");
let stories=[],ownerId="";
const escapeHTML=value=>String(value??"").replace(/[&<>'"]/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[char]));
function show(el,text){el.textContent=text;el.hidden=false}
function hide(el){el.hidden=true;el.textContent=""}
async function session(){const{data}=await client.auth.getSession();const email=data.session?.user.email;ownerId=data.session?.user.id||"";if(email===OWNER){login.hidden=true;studio.hidden=false;await load()}else{login.hidden=false;studio.hidden=true}}
document.querySelector("#loginForm").addEventListener("submit",async event=>{event.preventDefault();const email=document.querySelector("#email").value.trim().toLowerCase();if(email!==OWNER)return show(document.querySelector("#loginMessage"),"這個帳號沒有管理權限。");const{error}=await client.auth.signInWithOtp({email,options:{emailRedirectTo:location.href.split("#")[0]}});show(document.querySelector("#loginMessage"),error?error.message:"登入連結已寄出，請到信箱點擊。")});
document.querySelector("#logout").addEventListener("click",()=>client.auth.signOut());client.auth.onAuthStateChange(session);session();

async function load(){const[{data,error},{data:submissions,error:submissionError}]=await Promise.all([client.from("ownver_stories").select("*").order("sort_order").order("created_at"),client.from("ownver_customer_stories").select("*").order("created_at",{ascending:false})]);if(error)return show(message,error.message);stories=data||[];document.querySelector("#storyCount").textContent=`${stories.length} / 20`;document.querySelector("#submit").disabled=stories.length>=20&&!form.edit_id.value;library.innerHTML=stories.length?stories.map(story=>{const src=media(story.cover_path)||media(story.video_path),tag=story.cover_path?`<img class="item-media" src="${escapeHTML(src)}" alt="${escapeHTML(story.word)}">`:`<video class="item-media" src="${escapeHTML(src)}" preload="metadata"></video>`;return `<article class="item">${src?tag:'<div class="item-media"></div>'}<div><b>${escapeHTML(story.word)}</b><p>${escapeHTML(story.summary)}</p><small>${story.published?"已顯示":"未公開"} · 順序 ${story.sort_order}</small></div><div class="item-actions"><button data-edit="${story.id}">編輯</button><button class="danger" data-delete="${story.id}">刪除</button></div></article>`}).join(""):"<p>還沒有故事內容。</p>";if(submissionError){customerStories.innerHTML="<p>目前無法讀取問卷。</p>"}else customerStories.innerHTML=submissions?.length?submissions.map(item=>`<article class="submission"><b>${escapeHTML(item.word)}</b><p>${escapeHTML(item.story)}<br><small>${item.willing_to_publish?"願意接受公開聯絡":"不公開"}</small></p><small>${escapeHTML(item.contact)}<br>${new Date(item.created_at).toLocaleString("zh-TW")}</small></article>`).join(""):"<p>目前還沒有顧客問卷。</p>"}

function resetForm(){form.reset();form.sort_order.value=Math.min(stories.length+1,20);form.published.checked=true;form.edit_id.value="";mediaRemovals.hidden=true;removeVideoRow.hidden=true;removeCoverRow.hidden=true;document.querySelector("#formEyebrow").textContent="NEW STORY";document.querySelector("#formTitle").textContent="新增故事內容";document.querySelector("#submit").textContent="儲存故事";document.querySelector("#cancelEdit").hidden=true;document.querySelector("#submit").disabled=stories.length>=20;hide(message)}
document.querySelector("#cancelEdit").addEventListener("click",resetForm);
library.addEventListener("click",async event=>{const editButton=event.target.closest("button[data-edit]"),deleteButton=event.target.closest("button[data-delete]");if(editButton){const story=stories.find(item=>item.id===editButton.dataset.edit);if(!story)return;form.edit_id.value=story.id;form.word.value=story.word;form.summary.value=story.summary;form.story.value=story.story||"";form.sort_order.value=story.sort_order;form.published.checked=story.published;form.remove_video.checked=false;form.remove_cover.checked=false;removeVideoRow.hidden=!story.video_path;removeCoverRow.hidden=!story.cover_path;mediaRemovals.hidden=!story.video_path&&!story.cover_path;document.querySelector("#formEyebrow").textContent="EDIT STORY";document.querySelector("#formTitle").textContent=`編輯 ${story.word}`;document.querySelector("#submit").textContent="儲存修改";document.querySelector("#submit").disabled=false;document.querySelector("#cancelEdit").hidden=false;form.scrollIntoView({behavior:"smooth",block:"start"});return}if(deleteButton){const story=stories.find(item=>item.id===deleteButton.dataset.delete);if(!story||!confirm(`確定刪除 ${story.word}？刪除後無法復原。`))return;const removable=[story.video_path,story.cover_path].filter(path=>path&&!/^(https?:|assets\/)/.test(path));if(removable.length)await client.storage.from("ownver-media").remove(removable);const{error}=await client.from("ownver_stories").delete().eq("id",story.id);show(message,error?error.message:"已刪除");if(!error)resetForm();await load()}});

form.addEventListener("submit",async event=>{event.preventDefault();const values=new FormData(form),editId=String(values.get("edit_id")||""),existing=stories.find(item=>item.id===editId);if(!editId&&stories.length>=20)return show(message,"最多只能保留 20 組故事內容，請先刪除一組。");const video=values.get("video"),cover=values.get("cover"),removeVideo=values.get("remove_video")==="on",removeCover=values.get("remove_cover")==="on",button=document.querySelector("#submit");button.disabled=true;show(message,"正在儲存，請不要關閉頁面……");const uploaded=[];try{const key=`${Date.now()}-${crypto.randomUUID()}`;let videoPath=removeVideo?null:existing?.video_path||null,coverPath=removeCover?null:existing?.cover_path||null;if(video?.size){if(video.size>104857600)throw new Error("影片需小於 100MB");videoPath=`videos/${key}.${video.name.split(".").pop()}`;const result=await client.storage.from("ownver-media").upload(videoPath,video,{contentType:video.type});if(result.error)throw result.error;uploaded.push(videoPath)}if(cover?.size){coverPath=`covers/${key}.${cover.name.split(".").pop()}`;const result=await client.storage.from("ownver-media").upload(coverPath,cover,{contentType:cover.type});if(result.error)throw result.error;uploaded.push(coverPath)}const record={word:String(values.get("word")).trim().toUpperCase(),summary:String(values.get("summary")).trim(),story:String(values.get("story")).trim(),video_path:videoPath,cover_path:coverPath,sort_order:Number(values.get("sort_order")||stories.length+1),published:values.get("published")==="on"};let error;if(editId){({error}=await client.from("ownver_stories").update(record).eq("id",editId));if(!error){const replaced=[video?.size||removeVideo?existing?.video_path:null,cover?.size||removeCover?existing?.cover_path:null].filter(path=>path&&!/^(https?:|assets\/)/.test(path));if(replaced.length)await client.storage.from("ownver-media").remove(replaced)}}else({error}=await client.from("ownver_stories").insert({...record,owner_id:ownerId}));if(error)throw error;show(message,editId?"修改完成。":"新增完成。");await load();resetForm()}catch(error){if(uploaded.length)await client.storage.from("ownver-media").remove(uploaded);show(message,error.message||"儲存失敗");button.disabled=false}});
